import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.aJDz64y9.js";const u=JSON.parse('{"title":"Сквозные системы","description":"","frontmatter":{},"headers":[],"relativePath":"crime/systems.md","filePath":"crime/systems.md","lastUpdated":1794540927000}'),l={name:"crime/systems.md"};function o(s,t,i,n,h,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="сквозные-системы" tabindex="-1">Сквозные системы <a class="header-anchor" href="#сквозные-системы" aria-label="Permalink to &quot;Сквозные системы&quot;">​</a></h1><p>Пять систем общие для всех активностей: инструменты, краденое, скупка, улики и тревога. Их делают один раз, и каждая новая активность подключается к готовому.</p><h2 id="инструменты-и-черныи-рынок" tabindex="-1">Инструменты и чёрный рынок <a class="header-anchor" href="#инструменты-и-черныи-рынок" aria-label="Permalink to &quot;Инструменты и чёрный рынок&quot;">​</a></h2><p>Инструмент одновременно пропуск к ступени, расходник и товар между игроками. Источников два:</p><ul><li><strong>Барыга (NPC).</strong> Торгует из фургона, раз в сутки меняет точку, на карте виден только вблизи. Продаёт первую ступень и немного второй; дневной запас один на весь сервер. Сведение о том, где он сегодня, само становится товаром.</li><li><strong>Мастера (игроки).</strong> Собирают инструмент второй и третьей ступени на верстаке. Детали берутся из легальных магазинов и из краденого: электроника из налётов идёт на глушилки, сканеры и ретрансляторы. У NPC этот инструмент не продаётся, поэтому на мастеров есть спрос.</li></ul><table tabindex="0"><thead><tr><th>Инструмент</th><th>Что открывает</th><th>Шум и риск</th><th>Расход</th><th>Ступень</th></tr></thead><tbody><tr><td>Отмычки</td><td>Простые замки дверей, ящиков, старых машин</td><td>Тихо</td><td>Ломаются при ошибке</td><td>1</td></tr><tr><td>Фомка</td><td>Двери, шкафы, кассы — быстро</td><td>Громко, оставляет следы взлома</td><td>Почти не изнашивается</td><td>1</td></tr><tr><td>Болторез</td><td>Навесные замки, рольставни, замок щитка</td><td>Средне</td><td>Изнашивается</td><td>1–2</td></tr><tr><td>Стеклорез</td><td>Окна и витрины без звона</td><td>Тихо, но медленно</td><td>Диск на несколько резов</td><td>2</td></tr><tr><td>Набор электрика</td><td>Щиток: сигнализация, камеры, свет</td><td>Тихо; при ошибке удар током и тревога</td><td>Заряды</td><td>2</td></tr><tr><td>Дрель и свёрла</td><td>Сейфы</td><td>Очень громко</td><td>Свёрла</td><td>2–3</td></tr><tr><td>Стетоскоп</td><td>Сейфы с лимбом</td><td>Тихо, долго</td><td>Нет</td><td>3</td></tr><tr><td>Глушилка</td><td>Задерживает дозвон сигнализации и сигнал жучка</td><td>Нет</td><td>Батарея на несколько минут</td><td>2–3</td></tr><tr><td>Ретранслятор ключа</td><td>Современные машины; работает только вдвоём</td><td>Тихо</td><td>Батарея</td><td>3</td></tr><tr><td>Сканер жучков</td><td>Ищет трекеры в машине и метки в товаре</td><td>Нет</td><td>Нет</td><td>2</td></tr><tr><td>Перчатки и маска</td><td>Не оставляют отпечатков и примет</td><td>Нет</td><td>Изнашиваются</td><td>1</td></tr><tr><td>Сумка и тележка</td><td>Объём добычи; тележка возит сейфы и крупную технику</td><td>Тележка шумит</td><td>Нет</td><td>1–2</td></tr></tbody></table><h2 id="краденое" tabindex="-1">Краденое <a class="header-anchor" href="#краденое" aria-label="Permalink to &quot;Краденое&quot;">​</a></h2><p>Добыча — это предметы, а не деньги: их надо вынести, довезти, спрятать и продать.</p><ul><li><strong>Метка происхождения.</strong> У каждой вещи есть номер дела, время кражи и базовая цена; у техники и машин — серийный номер.</li><li><strong>Три габарита.</strong> Карманное: деньги, украшения, телефоны. Сумочное: ноутбуки, приставки, алкоголь. Ручное: телевизор, картина, сейф — одна вещь в руках, бежать нельзя, оружие убрано.</li><li><strong>Объём важнее веса.</strong> Стартовые значения: сумка на 20 единиц, багажник седана на две крупные вещи, фургон на восемь. Выбор машины становится решением: фургон вместителен, но ночью во дворе заметен.</li></ul><h2 id="скупка" tabindex="-1">Скупка <a class="header-anchor" href="#скупка" aria-label="Permalink to &quot;Скупка&quot;">​</a></h2><p>Публичного маркера скупки нет: NPC-скупщик назначает встречу по звонку и каждый раз в новом месте, а выгодный сбыт идёт через людей. В ROB RUN неподвижные точки сбыта за первые дни превратились в места засад — эту ошибку не повторяем.</p><table tabindex="0"><thead><tr><th>Канал</th><th>Кто покупает</th><th>Сколько платит</th><th>Ограничение</th><th>Риск</th></tr></thead><tbody><tr><td>NPC-скупщик</td><td>Система</td><td>40–50% базовой цены; цена категории падает, когда её сдают много</td><td>Суточный лимит, не берёт свежее</td><td>Низкий</td></tr><tr><td>Скупщик-игрок</td><td>Владелец ломбарда, точки на рынке или член группировки</td><td>По договорённости; сам сбывает оптом за 80–100%</td><td>Нужен склад и оборот</td><td>Обыск склада, палёные серийники</td></tr><tr><td>Заказ</td><td>NPC или игрок публикует список нужного</td><td>110–130% за точное попадание</td><td>Срок и количество</td><td>Засада: срок известен заранее</td></tr></tbody></table><p>Деньги в итоге даёт система, но в середине цепочки стоят люди со своей маржой. Отсюда торг, доверие, кидки и полицейские подставы.</p><h2 id="улики" tabindex="-1">Улики <a class="header-anchor" href="#улики" aria-label="Permalink to &quot;Улики&quot;">​</a></h2><p>Улики превращают преступление в дело, которое полиция может раскрыть через час или через день. Стартовый набор — три вида:</p><ul><li><strong>Камеры.</strong> Камера, которую не отключили, сохраняет приметы: одежду, наличие маски, машину и номер.</li><li><strong>Отпечатки.</strong> Без перчаток остаются на всём, что игрок трогал. Совпадение даёт только база тех, кого уже оформляли.</li><li><strong>Серийники.</strong> Техника и машины несут номер. Вещь, найденная у скупщика, ведёт по журналу сделок к тому, кто её сдал.</li></ul><p>Следы обуви, кровь и следы инструмента добавляются позже, когда у полиции появится привычка работать с делами.</p><h2 id="тревога-и-полиция" tabindex="-1">Тревога и полиция <a class="header-anchor" href="#тревога-и-полиция" aria-label="Permalink to &quot;Тревога и полиция&quot;">​</a></h2><p>У каждого объекта четыре состояния: спокойно, подозрение, тревога, блокировка. Переводят между ними шум, свидетели, датчики и тревожная кнопка продавца.</p><ul><li><strong>Вызов зависит от источника.</strong> Сигнализация даёт точный адрес. Звонок соседа даёт примерный квартал и расплывчатое описание, тем хуже, чем лучше замаскирована команда.</li><li><strong>Ёмкость полиции.</strong> Каждое активное дело занимает экипажи по два полицейских: первая ступень — один экипаж, вторая — два, третья — четыре. Занято может быть не больше половины полицейских в сети. При 30–40 в прайм это до двух дел третьей ступени одновременно, ночью при 15–20 — одно. Когда ёмкость исчерпана, новые дела верхних ступеней не открываются, а первая ступень идёт с ответом NPC-охраны.</li><li><strong>Выход без стрельбы.</strong> Сдавшийся теряет добычу и инструмент, но не всё имущество. Это делает сдачу разумным выбором и снижает число перестрелок ради сумки с телевизором.</li></ul>',20)])])}const g=d(l,[["render",o]]);export{u as __pageData,g as default};
